import React,{useState,useEffect} from 'react';import {supabase} from '../lib/supabase';import {useAuth} from '../contexts/AuthContext';import {BarChart3,Download,FileText,Calendar,TrendingUp,Package,DollarSign,Filter,RefreshCw,AlertCircle} from 'lucide-react';import toast from 'react-hot-toast';
export default function Reports(){const {storeId,staff}=useAuth();const [activeTab,setActiveTab]=useState('sales');const [dateRange,setDateRange]=useState('today');const [customStart,setCustomStart]=useState('');const [customEnd,setCustomEnd]=useState('');const [loading,setLoading]=useState(false);const [error,setError]=useState(null);const [salesData,setSalesData]=useState([]);const [profitData,setProfitData]=useState(null);const [inventoryValue,setInventoryValue]=useState({totalCost:0,totalRetail:0,potentialProfit:0,items:[]});const [companySettings,setCompanySettings]=useState({currency_symbol:'K'});const isManager=staff?.role==='admin'||staff?.role==='manager';
useEffect(()=>{if(storeId){supabase.from('company_settings').select('currency_symbol').eq('store_id',storeId).single().then(({data})=>{if(data)setCompanySettings(data);}).catch(()=>{});}},[storeId]);
const getDateRange=()=>{const now=new Date();let start=new Date();let end=new Date();switch(dateRange){case'today':start.setHours(0,0,0,0);end.setHours(23,59,59,999);break;case'yesterday':start.setDate(start.getDate()-1);start.setHours(0,0,0,0);end.setDate(end.getDate()-1);end.setHours(23,59,59,999);break;case'thisWeek':const day=now.getDay();start.setDate(now.getDate()-day);start.setHours(0,0,0,0);end.setHours(23,59,59,999);break;case'thisMonth':start.setDate(1);start.setHours(0,0,0,0);end.setHours(23,59,59,999);break;case'lastMonth':start.setMonth(start.getMonth()-1,1);start.setHours(0,0,0,0);end.setMonth(end.getMonth(),0);end.setHours(23,59,59,999);break;case'custom':if(customStart&&customEnd){start=new Date(customStart);end=new Date(customEnd);end.setHours(23,59,59,999);}break;default:break;}return{start:start.toISOString(),end:end.toISOString()};};
const loadSalesReport=async()=>{if(!storeId)return;setLoading(true);setError(null);try{const {start,end}=getDateRange();const {data,error}=await supabase.from('sales').select('*,customer:customers(name),staff:staff(full_name)').eq('store_id',storeId).eq('returned',false).gte('created_at',start).lte('created_at',end).order('created_at',{ascending:false});if(error)throw error;setSalesData(data||[]);}catch(err){setError(err.message);toast.error('Failed to load sales');}finally{setLoading(false);}};
const loadProfitReport=async()=>{if(!storeId)return;setLoading(true);setError(null);try{const {start,end}=getDateRange();const {data:sales}=await supabase.from('sales').select('total_amount').eq('store_id',storeId).eq('returned',false).gte('created_at',start).lte('created_at',end);const {data:items}=await supabase.from('sale_items').select('quantity,cost_price').gte('created_at',start).lte('created_at',end);const rev=sales?.reduce((s,i)=>s+i.total_amount,0)||0;const cost=items?.reduce((s,i)=>s+(i.cost_price*i.quantity),0)||0;const profit=rev-cost;const margin=rev>0?(profit/rev)*100:0;setProfitData({totalRevenue:rev,totalCost:cost,grossProfit:profit,margin,transactionCount:sales?.length||0});}catch(err){setError(err.message);toast.error('Failed to load profit');}finally{setLoading(false);}};
const loadInventoryValuation=async()=>{if(!storeId)return;setLoading(true);setError(null);try{const {data,error}=await supabase.from('products').select('name,stock_quantity,cost_price,unit_price').eq('store_id',storeId).eq('is_active',true);if(error)throw error;let totalCost=0,totalRetail=0;const items=data.map(p=>{const cv=(p.cost_price||0)*p.stock_quantity;const rv=p.unit_price*p.stock_quantity;totalCost+=cv;totalRetail+=rv;return{...p,costValue:cv,retailValue:rv};});setInventoryValue({totalCost,totalRetail,potentialProfit:totalRetail-totalCost,items});}catch(err){setError(err.message);toast.error('Failed to load inventory');}finally{setLoading(false);}};
const handleLoadReport=()=>{if(activeTab==='sales')loadSalesReport();else if(activeTab==='profit')loadProfitReport();else if(activeTab==='inventory')loadInventoryValuation();};
useEffect(()=>{if(storeId){if(activeTab==='sales')loadSalesReport();else if(activeTab==='profit')loadProfitReport();else if(activeTab==='inventory')loadInventoryValuation();}},[storeId,activeTab]);
const exportToCSV=(data,filename)=>{if(!data.length)return toast.error('No data');const headers=Object.keys(data[0]);const csv=[headers.join(','),...data.map(r=>headers.map(h=>JSON.stringify(r[h]||'')).join(','))].join('\n');const blob=new Blob([csv],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();};
const formatCurrency=v=>`${companySettings.currency_symbol}${v.toFixed(2)}`;
if(!isManager)return<div className="p-8 text-red-600">Access Denied</div>;
return(<div className="p-4 h-full overflow-y-auto"><div className="flex items-center gap-2 mb-4"><h1 className="text-2xl font-bold"><BarChart3 className="inline mr-2"/>Reports</h1>{error&&<button onClick={handleLoadReport} className="ml-auto px-3 py-1 bg-blue-600 text-white rounded flex items-center gap-1"><RefreshCw size={14}/>Retry</button>}</div>{error&&<div className="mb-4 p-4 bg-red-50 border border-red-200 rounded-lg flex items-center gap-2"><AlertCircle className="text-red-600"/><span className="text-red-700">{error}</span></div>}<div className="flex gap-2 mb-4 border-b">{['sales','profit','inventory'].map(t=>(<button key={t} onClick={()=>setActiveTab(t)} className={`px-4 py-2 font-medium capitalize ${activeTab===t?'text-green-600 border-b-2 border-green-600':'text-gray-500'}`}>{t==='sales'&&<DollarSign className="inline mr-1" size={16}/>}{t==='profit'&&<TrendingUp className="inline mr-1" size={16}/>}{t==='inventory'&&<Package className="inline mr-1" size={16}/>}{t}</button>))}</div><div className="bg-white p-4 rounded-lg shadow mb-4 flex flex-wrap gap-3 items-end"><div><label className="block text-sm mb-1">Date Range</label><select value={dateRange} onChange={e=>setDateRange(e.target.value)} className="p-2 border rounded"><option value="today">Today</option><option value="yesterday">Yesterday</option><option value="thisWeek">This Week</option><option value="thisMonth">This Month</option><option value="lastMonth">Last Month</option><option value="custom">Custom</option></select></div>{dateRange==='custom'&&(<><div><label className="block text-sm mb-1">Start</label><input type="date" value={customStart} onChange={e=>setCustomStart(e.target.value)} className="p-2 border rounded"/></div><div><label className="block text-sm mb-1">End</label><input type="date" value={customEnd} onChange={e=>setCustomEnd(e.target.value)} className="p-2 border rounded"/></div></>)}<button onClick={handleLoadReport} disabled={loading} className="px-4 py-2 bg-green-600 text-white rounded flex items-center gap-2"><Filter size={16}/>{loading?'Loading...':'Apply'}</button>{activeTab==='sales'&&salesData.length>0&&(<><button onClick={()=>exportToCSV(salesData,`sales_${dateRange}.csv`)} className="px-4 py-2 bg-blue-600 text-white rounded"><Download size={16}/>CSV</button><button onClick={()=>window.print()} className="px-4 py-2 bg-gray-600 text-white rounded"><FileText size={16}/>PDF</button></>)}</div>{loading?<div className="text-center py-8">Loading...</div>:<>{activeTab==='sales'&&(<div className="bg-white rounded-lg shadow overflow-hidden"><div className="p-4 border-b flex justify-between"><h2 className="font-bold">Sales ({salesData.length})</h2><p>Total: {formatCurrency(salesData.reduce((s,i)=>s+i.total_amount,0))}</p></div><div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-gray-50"><tr><th className="p-2">Invoice</th><th className="p-2">Date</th><th className="p-2">Customer</th><th className="p-2">Cashier</th><th className="p-2">Payment</th><th className="p-2 text-right">Total</th></tr></thead><tbody>{salesData.map(s=>(<tr key={s.id} className="border-t"><td className="p-2">{s.invoice_number}</td><td className="p-2">{new Date(s.created_at).toLocaleString()}</td><td className="p-2">{s.customer?.name||'Walk-in'}</td><td className="p-2">{s.staff?.full_name}</td><td className="p-2">{s.payment_method}</td><td className="p-2 text-right">{formatCurrency(s.total_amount)}</td></tr>))}</tbody></table></div></div>)}{activeTab==='profit'&&profitData&&(<div className="space-y-4"><div className="grid grid-cols-2 md:grid-cols-4 gap-4"><div className="bg-white p-4 rounded-lg shadow"><p className="text-gray-500">Revenue</p><p className="text-2xl font-bold">{formatCurrency(profitData.totalRevenue)}</p></div><div className="bg-white p-4 rounded-lg shadow"><p className="text-gray-500">Cost</p><p className="text-2xl font-bold">{formatCurrency(profitData.totalCost)}</p></div><div className="bg-white p-4 rounded-lg shadow"><p className="text-gray-500">Profit</p><p className="text-2xl font-bold text-green-600">{formatCurrency(profitData.grossProfit)}</p></div><div className="bg-white p-4 rounded-lg shadow"><p className="text-gray-500">Margin</p><p className="text-2xl font-bold">{profitData.margin.toFixed(1)}%</p></div></div></div>)}{activeTab==='inventory'&&(<div className="space-y-4"><div className="grid grid-cols-1 md:grid-cols-3 gap-4"><div className="bg-white p-4 rounded-lg shadow"><p className="text-gray-500">Cost Value</p><p className="text-2xl font-bold">{formatCurrency(inventoryValue.totalCost)}</p></div><div className="bg-white p-4 rounded-lg shadow"><p className="text-gray-500">Retail Value</p><p className="text-2xl font-bold">{formatCurrency(inventoryValue.totalRetail)}</p></div><div className="bg-white p-4 rounded-lg shadow"><p className="text-gray-500">Potential Profit</p><p className="text-2xl font-bold text-green-600">{formatCurrency(inventoryValue.potentialProfit)}</p></div></div><div className="bg-white rounded-lg shadow overflow-hidden"><div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-gray-50"><tr><th className="p-2">Product</th><th className="p-2 text-right">Stock</th><th className="p-2 text-right">Cost/Unit</th><th className="p-2 text-right">Price/Unit</th><th className="p-2 text-right">Cost Value</th><th className="p-2 text-right">Retail Value</th></tr></thead><tbody>{inventoryValue.items.map((item,i)=>(<tr key={i} className="border-t"><td className="p-2">{item.name}</td><td className="p-2 text-right">{item.stock_quantity}</td><td className="p-2 text-right">{formatCurrency(item.cost_price||0)}</td><td className="p-2 text-right">{formatCurrency(item.unit_price)}</td><td className="p-2 text-right">{formatCurrency(item.costValue)}</td><td className="p-2 text-right">{formatCurrency(item.retailValue)}</td></tr>))}</tbody></table></div></div></div>)}</>}</div>);}
